/* GraphPaper — local-first writing studio. No CDN, analytics or browser API keys. */
'use strict';
const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const esc = v => String(v ?? '').replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid = ()=>'ui_'+(crypto.randomUUID?crypto.randomUUID().replaceAll('-',''):Date.now().toString(16)+Math.random().toString(16).slice(2)).slice(0,12);
const storage={getItem:k=>{try{return window.localStorage.getItem(k);}catch{return null;}},setItem:(k,v)=>{try{window.localStorage.setItem(k,v);}catch{ /* Private-browser storage may be unavailable. */ }}};
const words = t=>(String(t||'').match(/\S+/g)||[]).length;
const fmt = n=>Number(n||0).toLocaleString();
const icons={
 plus:'M12 5v14M5 12h14', arrow:'M5 12h14m-6-6 6 6-6 6', back:'M19 12H5m6-6-6 6 6 6',
 graph:'M8 6l8 3M7 8l3 8m6-4-4 5M7 5a2 2 0 1 0 0 .1M18 9a2 2 0 1 0 0 .1M11 18a2 2 0 1 0 0 .1',
 book:'M3 4h6a4 4 0 0 1 3 2 4 4 0 0 1 3-2h6v15h-6a4 4 0 0 0-3 2 4 4 0 0 0-3-2H3zM12 6v15',
 file:'M14 2H5v20h14V7zM14 2v5h5M8 12h8M8 16h6', upload:'M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5',
 download:'M12 3v13m-5-5 5 5 5-5M4 16v5h16v-5', spark:'m12 3 2.7 6.3L21 12l-6.3 2.7L12 21l-2.7-6.3L3 12l6.3-2.7z',
 pen:'m16 3 5 5-12 12-6 1 1-6zM13 6l5 5', list:'M8 6h13M8 12h13M8 18h13M3 6h.1M3 12h.1M3 18h.1',
 settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2',
 check:'m5 12 4 4L19 6', x:'m6 6 12 12M6 18 18 6', search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14m5 12 6 6',
 pin:'m9 3 6 0-1 6 4 4-5 0-1 8-1-8H6l4-4z', eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12M12 9a3 3 0 1 0 0 6 3 3 0 0 0 0-6',
 clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18M12 7v5l3 2', sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1',
 link:'m10 13 4-4M8 16l-1 1a4 4 0 0 1-6-6l4-4a4 4 0 0 1 6 0m2 2 1-1a4 4 0 0 1 6 6l-4 4a4 4 0 0 1-6 0',
 lock:'M5 10h14v11H5zM8 10V6a4 4 0 0 1 8 0v4', chevron:'m8 5 7 7-7 7', up:'m6 14 6-6 6 6', down:'m6 10 6 6 6-6',
 menu:'M3 6h18M3 12h18M3 18h18', expand:'M3 9V3h6m6 0h6v6M3 15v6h6m6 0h6v-6', minus:'M5 12h14',
 trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7', alert:'m12 3 10 18H2zM12 9v5m0 3v.1',
 branch:'M6 3v14a3 3 0 1 0 3 3M6 9h9a3 3 0 0 0 3-3V3', help:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18M9 9a3 3 0 1 1 4 3l-1 1v1m0 3v.1',
 folder:'M3 5h6l2 2h10v14H3z', stop:'M6 6h12v12H6z', refresh:'M20 9a8 8 0 0 0-14-4L3 8m0-5v5h5M4 15a8 8 0 0 0 14 4l3-3m0 5v-5h-5'
};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.55" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.file}"/></svg>`;
const btn=(label,act,ic='',cls='',attrs='')=>`<button type="button" class="button ${cls}" data-action="${act}" ${attrs}>${ic?icon(ic):''}${esc(label)}</button>`;
const ibtn=(title,act,ic,attrs='')=>`<button type="button" class="icon-btn" aria-label="${esc(title)}" title="${esc(title)}" data-action="${act}" ${attrs}>${icon(ic)}</button>`;
const steps=[['sources','Sources','file'],['graph','Graph','graph'],['angles','Angles','spark'],['outline','Outline','list'],['write','Write','pen']];
const state={p:null,projects:[],settings:{},tab:'sources',node:null,edge:null,path:[],view:'split',job:null,save:'Saved locally',layout:{},search:'',relations:false};
let pending={},timer=null,saveChain=Promise.resolve(),pollTimer=null,focusBeforeModal=null;
async function api(path,body,method){
 const opt={method:method||(body===undefined?'GET':'POST'),headers:{'X-GraphPaper':'1'},credentials:'same-origin'};
 if(body!==undefined){if(body instanceof FormData)opt.body=body;else{opt.headers['Content-Type']='application/json';opt.body=JSON.stringify(body);}}
 const res=await fetch('/api'+path,opt); let data;
 try{data=await res.json();}catch{data={detail:`Request failed (${res.status}).`};}
 if(!res.ok){const detail=Array.isArray(data.detail)?data.detail.map(x=>x.msg).join('; '):data.detail;throw new Error(detail||`Request failed (${res.status})`);}
 return data;
}
function toast(text,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.innerHTML=icon(error?'alert':'check')+`<span>${esc(text)}</span>`;$('#toasts').append(el);setTimeout(()=>el.remove(),error?16000:5000);}
function busy(){return state.job&&['queued','running'].includes(state.job.state);}
function editable(){if(busy()){toast('Let this job finish, or cancel it, before editing the project.',true);return false;}return true;}
function updateSaved(label){state.save=label;$$('.saved').forEach(e=>e.innerHTML=icon(label==='Saved locally'?'check':'clock')+esc(label));}
function queueSave(patch){Object.assign(pending,patch);updateSaved('Unsaved changes');clearTimeout(timer);timer=setTimeout(()=>flush().catch(e=>toast(e.message,true)),650);}
async function flush(){
 clearTimeout(timer); const patch=pending;pending={}; if(!state.p||!Object.keys(patch).length)return saveChain;
 const pid=state.p.id;updateSaved('Saving…');
 saveChain=saveChain.catch(()=>{}).then(async()=>{
  if(!state.p||state.p.id!==pid)throw new Error('Project changed before saving.');
  try{const saved=await api('/projects/'+pid,{version:state.p.version,...patch},'PATCH');
   const queued={...pending};state.p=saved;Object.assign(state.p,queued);syncSummary();updateSaved(Object.keys(pending).length?'Unsaved changes':'Saved locally');
  }catch(e){pending={...patch,...pending};updateSaved('Not saved — retry');throw e;}
 });return saveChain;
}
function syncSummary(){if(!state.p)return;const p=state.p;const summary={id:p.id,title:p.title,mode:p.mode,updated:p.updated,sources:p.sources.length,words:words(p.draft)};const i=state.projects.findIndex(x=>x.id===p.id);if(i<0)state.projects.unshift(summary);else state.projects[i]={...state.projects[i],...summary};}
async function setProject(p,tab){await flush();clearTimeout(pollTimer);state.p=p;pending={};state.node=null;state.edge=null;state.path=[];state.search='';state.job=null;state.layout={};state.tab=tab||(p.graph.nodes.length?'graph':'sources');syncSummary();storage.setItem('graphpaper.last',p.id);render();}
async function openProject(id){await flush();const p=await api('/projects/'+id);await setProject(p);const boot=await api('/bootstrap');const j=boot.jobs.find(j=>j.project_id===id);if(j){state.job=j;render();poll();}}
function showModal(title,sub,body,foot='',wide=false){focusBeforeModal=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-head"><div><h2 id="modal-title">${esc(title)}</h2><p>${esc(sub)}</p></div>${ibtn('Close dialog','close-modal','x')}</header><div class="modal-body">${body}</div>${foot?`<footer class="modal-foot"><span class="modal-status" id="modal-status"></span>${foot}</footer>`:''}</section></div>`;setTimeout(()=>$('.modal input:not([type=hidden]),.modal textarea,.modal select,.modal button')?.focus(),0);}
function closeModal(){ $('#modal-root').innerHTML='';focusBeforeModal?.focus?.();}
function modalError(msg){const e=$('#modal-status');if(e){e.textContent=msg;e.classList.add('error-inline');}else toast(msg,true);}
function selectedAngle(){return state.p?.angles.find(a=>a.id===state.p.selected_angle);}
function progressDone(t){const p=state.p;return t==='sources'?p.sources.length>0:t==='graph'?p.graph.nodes.length>0:t==='angles'?!!selectedAngle():t==='outline'?p.outline.length>0:!!p.draft;}
function render(){
 const p=state.p,s=state.settings;
 document.documentElement.dataset.theme=s.theme||'dark';
 $('#app').innerHTML=`<div class="shell"><aside class="sidebar"><a class="brand" href="#" data-action="home"><img src="/static/icon.svg" alt=""><div><strong>GraphPaper</strong><small>A studio for connected thought</small></div></a>${btn('New project','new','plus','new')}<div class="caps">Your workspace</div><div class="project-list">${state.projects.map(x=>`<button class="project-item ${x.id===p?.id?'active':''}" data-action="open-project" data-id="${esc(x.id)}"><span class="project-letter">${icon(x.mode==='fiction'?'book':'file')}</span><span class="project-name">${esc(x.title)}<small>${x.mode==='fiction'?'Fiction':x.mode==='science'?'Science':x.mode==='polemic'?'Polemic':'Nonfiction'}</small></span></button>`).join('')||'<p class="side-note">Your stories and ideas live here.</p>'}</div>${p?`<div class="nav-section"><div class="caps">Studio</div>${steps.map(([t,label,ic])=>`<button class="nav-link ${state.tab===t?'active':''}" data-action="tab" data-tab="${t}">${icon(ic)}${label}<span class="spacer"></span>${t==='sources'?`<span class="nav-count">${p.sources.length}</span>`:t==='angles'&&p.angles.length?`<span class="nav-count">${p.angles.length}</span>`:''}</button>`).join('')}</div>`:''}<div class="side-bottom"><div class="side-note">${icon('lock')} Local projects. Your models.<br>Nothing leaves without your permission.</div><button class="nav-link" data-action="settings">${icon('settings')} Connections & settings</button><button class="nav-link" data-action="help">${icon('help')} How this studio works</button><div class="row between mt12"><span class="tiny muted">GraphPaper · 0.6.0</span>${ibtn('Switch theme','theme','sun')}</div></div></aside><main><header class="topbar"><div class="row">${'<button class="icon-btn mobile-menu" data-action="menu" aria-label="Menu">'+icon('menu')+'</button>'}<div class="breadcrumb">Studio ${p?`<span>/</span> ${esc(p.mode==='fiction'?'Fiction':'Nonfiction')}`:''}</div></div><div class="header-actions"><span class="saved">${icon('check')}${esc(state.save)}</span>${p?ibtn('Project options','project-options','settings'):''}${btn(p?'Export':'Import project',p?'export':'import-project',p?'download':'upload','small')}</div></header>${p?projectHTML():welcomeHTML()}</main></div>`;
 if(p&&state.tab==='graph'&&p.graph.nodes.length)requestAnimationFrame(drawGraph);
 setupDrops();paintJob();
}
function welcomeHTML(){return `<div class="welcome"><span class="chip green">${icon('graph')} FROM SOURCES TO SOMETHING NEW</span><h1>Good writing begins<br>with a connection.</h1><p>Bring your material. Find the relationships worth following. Shape an argument—or a world—and make it unmistakably yours.</p><div class="welcome-grid"><button class="panel welcome-card" data-action="new" data-mode="nonfiction">${icon('file')}<h3>Make a case.</h3><p>Essays, articles and research-led writing. Follow the evidence without losing your point of view.</p></button><button class="panel welcome-card" data-action="new" data-mode="fiction">${icon('book')}<h3>Build a world.</h3><p>Characters, tensions and consequences. Write fiction that remembers its own rules.</p></button></div><div class="welcome-end">Explore an example ${btn('The city after dark','demo','','small','data-mode="nonfiction"')}${btn('Borrowed mornings','demo','','small','data-mode="fiction"')}</div><div class="notice">The examples are original, illustrative workspaces—not factual research. Add a model connection to generate new writing; browsing, editing and exporting work without one.</div></div>`;}
function projectHTML(){const p=state.p;const names={sources:['A place for your material.','Add evidence, inspiration, a voice sample or the rules of your world.'],graph:['The connections are the beginning.','Explore the shape of your material. Pin what matters. Find a different way through.'],angles:['Find the story worth telling.','Different interpretations, not six versions of the same headline. You make the final choice.'],outline:['Give the idea a backbone.','Move the sections. Change the emphasis. Make the structure serve the writing.'],write:['Make every sentence earn its place.','Write, revise and check the work. Every generated draft has a recoverable version.']};const [title,desc]=names[state.tab];
 const primary={sources:['Build graph','run-graph','graph'],graph:['Discover angles','run-angles','spark'],angles:['Develop outline','run-outline','list'],outline:['Write draft','run-draft','pen'],write:['Review draft','run-review','check']}[state.tab];
 return `<div class="workspace-head"><div><div class="row gap4"><span class="caps">${esc(p.title)}</span>${p.demo?'<span class="chip gold">Illustrative example</span>':''}</div><h1>${title}</h1><p class="description">${desc}</p></div><div class="header-actions">${btn('Creative brief','brief','settings','ghost small')}${btn(primary[0],primary[1],primary[2],'primary',busy()?'disabled':'')}</div></div><nav class="steps" aria-label="Writing workflow">${steps.map(([t,label],i)=>`${i?'<span class="step-rule"></span>':''}<button class="step ${state.tab===t?'active':progressDone(t)?'done':''}" data-action="tab" data-tab="${t}" ${state.tab===t?'aria-current="step"':''}><span>${progressDone(t)&&state.tab!==t?'✓':i+1}</span>${label}</button>`).join('')}</nav><div id="job-slot"></div><div class="workspace-body">${({sources:sourcesHTML,graph:graphHTML,angles:anglesHTML,outline:outlineHTML,write:writeHTML}[state.tab])()}</div>`;
}
function empty(title,text,button,act,ic='spark'){return `<div class="panel"><div class="empty">${icon(ic)}<h2>${esc(title)}</h2><p>${esc(text)}</p><div class="empty-actions">${btn(button,act,ic,'primary',busy()?'disabled':'')}</div></div></div>`;}
function sourcesHTML(){const p=state.p;return `<div class="toolbar"><div><h2 class="section-title">Source library <span class="muted">${p.sources.length.toString().padStart(2,'0')}</span></h2><p class="section-desc">Original passages remain attached to the ideas extracted from them.</p></div><div class="row">${btn('Paste text','paste','file','small')}${btn('Add URL','url','link','small')}</div></div><div class="dropzone" id="dropzone" role="button" tabindex="0" data-action="upload"><div class="upload-circle">${icon('upload')}</div><strong>Drop your sources here</strong><p>or choose files · PDF, Word, Markdown, text, HTML · up to 20 MB each</p><span class="tiny muted">Documents stay on this device until you explicitly run an AI action.</span></div><div class="source-grid mt20">${p.sources.map(s=>`<article class="source-card ${!s.enabled?'disabled':''}"><div class="source-top"><span class="doc-icon">${icon(s.role==='canon'?'book':'file')}</span><div class="spacer"><span class="tiny muted">${esc(s.id)} · ${esc(s.kind.toUpperCase())}</span><h3>${esc(s.title)}</h3></div>${ibtn('Read source','source','eye',`data-id="${esc(s.id)}"`)}</div><p class="excerpt">${esc(s.text.slice(0,200))}${s.text.length>200?'…':''}</p><div class="source-bottom"><span class="chip ${s.role==='canon'?'gold':''}">${esc(s.role)}</span><span>${fmt(words(s.text))} words</span><button class="text-link" data-action="source-toggle" data-id="${esc(s.id)}">${s.enabled?'Enabled':'Excluded'}</button></div>${s.warnings.length?`<div class="notice">${esc(s.warnings.join(' '))}</div>`:''}</article>`).join('')}</div><div class="row mt20 wrap">${btn('Build knowledge graph','run-graph','graph','primary',busy()?'disabled':'')}${btn('Import existing graph','import-graph','upload','ghost small')}<span class="tiny muted">${p.mode==='fiction'?'Fiction can start from a premise and canon in the Creative brief.':'Graph extraction reads every enabled source chunk, within the job budget.'}</span></div>`;}
function directionHTML(){const p=state.p,b=p.brief;const n=p.graph.nodes.find(n=>n.id===state.node),e=p.graph.edges.find(e=>e.id===state.edge);const selected=n||e;return `<aside class="panel direction-panel"><div class="panel-header"><h2 class="section-title">Your direction</h2>${ibtn('Edit full creative brief','brief','settings')}</div><div class="panel-body"><label class="direction-label" for="direction">What should this piece explore?</label><textarea id="direction" data-brief="direction" rows="4" placeholder="An unexpected connection, a question, a feeling…" ${busy()?'disabled':''}>${esc(b.direction)}</textarea><div class="range-row"><label for="originality">Exploration</label><span id="originality-value">${b.originality}%</span></div><input id="originality" data-brief="originality" type="range" min="0" max="100" value="${b.originality}" ${busy()?'disabled':''}><div class="range-ends"><span>Familiar ground</span><span>Unexpected bridges</span></div><div class="range-row"><label for="rigor">${p.mode==='fiction'?'Canon discipline':'Evidence detail'}</label><span id="rigor-value">${b.rigor}%</span></div><input id="rigor" data-brief="rigor" type="range" min="0" max="100" value="${b.rigor}" ${busy()?'disabled':''}><p class="hint">${p.mode==='fiction'?'Invent freely. Treat established canon as a constraint unless you explicitly change it.':'A surprising connection is an invitation to investigate—not evidence of causation.'}</p>${b.pinned_nodes.length?`<div class="caps mt20">Pinned ideas</div><div class="pin-list">${b.pinned_nodes.map(id=>`<button class="pin" data-action="unpin" data-id="${esc(id)}">${icon('pin')}${esc(p.graph.nodes.find(n=>n.id===id)?.label||id)} ×</button>`).join('')}</div>`:''}${b.excluded_nodes.length?`<div class="mt12 tiny muted">${b.excluded_nodes.length} excluded ${btn('Reset exclusions','clear-exclusions','','small ghost')}</div>`:''}${selected?`<div class="evidence-card mt20"><div class="caps">${n?esc(n.kind):'Relationship'}</div><h3>${esc(n?n.label:e.relation.replaceAll('_',' '))}</h3><p class="small muted">${esc(selected.description)}</p><span class="chip ${selected.status==='sourced'?'green':'gold'}">${esc(selected.status)}</span>${(selected.evidence||[]).map((ev,i)=>`<blockquote>${esc(ev.quote)}</blockquote><button class="text-link" data-action="evidence" data-index="${i}">${esc(ev.source_id)} · ${ev.verified?'Exact source match':'Unverified anchor'} ${icon('chevron')}</button>`).join('')||'<p class="hint">No verified source anchor. Inspect the original before relying on this relationship.</p>'}${n?`<div class="row mt12 wrap">${btn(b.pinned_nodes.includes(n.id)?'Unpin':'Pin idea',b.pinned_nodes.includes(n.id)?'unpin':'pin','pin','small',`data-id="${esc(n.id)}"`)}${btn(b.excluded_nodes.includes(n.id)?'Include':'Exclude','exclude','','small ghost',`data-id="${esc(n.id)}"`)}</div>`:''}</div>`:`<div class="evidence-card mt20"><span class="caps">Follow the thread</span><p class="hint">Select a node or relationship to inspect its source. Drag to rearrange. Scroll to zoom.</p></div>`}</div></aside>`;}
function graphHTML(){const p=state.p;if(!p.graph.nodes.length)return empty('Start with a connection.','Upload sources or, for fiction, write a premise in your Creative brief. Then extract the graph.','Build graph','run-graph','graph');return `<div class="two-pane"><div><div class="panel graph-panel"><div class="graph-bar"><div class="graph-search">${icon('search')}<input id="graph-search" aria-label="Find an idea in the graph" placeholder="Find an idea…" value="${esc(state.search)}"></div><div class="graph-controls">${ibtn('Zoom in','zoom-in','plus')}${ibtn('Zoom out','zoom-out','minus')}${ibtn('Fit graph','fit-graph','expand')}${ibtn('Find a path','find-path','branch')}</div></div><svg class="graph-canvas" id="graph-svg" viewBox="0 0 900 590" role="img" aria-label="Interactive knowledge graph"></svg><div class="graph-footer"><div class="legend"><span><i style="background:var(--accent)"></i>Idea</span><span><i style="background:var(--blue)"></i>Claim / character</span><span><i style="background:var(--gold)"></i>Tension / event</span></div><span class="muted">Drag to explore · scroll to zoom</span></div></div><div class="toolbar mt12"><span class="tiny muted">${p.graph.nodes.length} nodes · ${p.graph.edges.length} relationships · ${esc(p.graph.engine||'native')}<span id="graph-visibility"></span></span><div class="row">${btn('Rebuild','run-graph','refresh','small ghost',busy()?'disabled':'')}${btn('Import','import-graph','upload','small ghost')}</div></div>${p.graph.warnings.slice(0,3).map(w=>`<div class="notice">${esc(w)}</div>`).join('')}${state.path.length?`<div class="notice">Conceptual path: ${state.path.map(id=>esc(p.graph.nodes.find(n=>n.id===id)?.label||id)).join(' → ')}. This path does not establish causation.</div>`:''}</div>${directionHTML()}</div>`;}
function anglesHTML(){const p=state.p;if(!p.angles.length)return empty('A graph is a possibility space.','Discover several distinct arguments or story premises, then choose or write the one you actually want.','Discover angles','run-angles')+'<div class="row mt20">'+btn('Write your own angle','custom-angle','pen','ghost')+'</div>';return `<div class="toolbar"><div><h2 class="section-title">Possible directions</h2><p class="section-desc">${p.selected_angle?'A direction is selected. Edit it freely before outlining.':'Choose a direction—or bring your own.'}</p></div><div class="row">${btn('Your own angle','custom-angle','plus','small')}${btn('Explore again','run-angles','refresh','small',busy()?'disabled':'')}</div></div><div class="two-pane"><div class="angle-grid">${p.angles.map((a,i)=>`<article class="angle-card ${a.id===p.selected_angle?'selected':''}"><div class="row between"><span class="angle-rank">DIRECTION ${String(i+1).padStart(2,'0')}</span><span class="chip ${a.id===p.selected_angle?'green':''}">${esc(a.motif||'Author direction')}</span></div><h2>${esc(a.title)}</h2><p class="thesis">${esc(a.thesis)}</p><p class="angle-why">${esc(a.why)}</p>${a.decision&&a.decision!=='unscored'?`<div class="tiny muted mt12">${esc(a.decision)}</div>`:''}<div class="angle-foot"><span class="angle-score">${a.score==null?'Not scored':`${Math.round(a.score)} / 100 · ${esc(a.score_engine||'editorial')}`}</span><div class="row">${ibtn('Edit angle','edit-angle','pen',`data-id="${esc(a.id)}"`)}${btn(a.id===p.selected_angle?'Selected':'Take this angle','select-angle',a.id===p.selected_angle?'check':'arrow',a.id===p.selected_angle?'small':'small primary',`data-id="${esc(a.id)}" ${busy()?'disabled':''}`)}</div></div><details class="angle-detail"><summary>Evidence & questions</summary><div class="mt12 small muted">${esc(a.counterargument||'No counterargument recorded yet.')}</div>${a.questions.map(q=>`<p class="question">${icon('help')}${esc(q)}</p>`).join('')}<div class="row wrap mt12">${a.source_ids.map(id=>btn(id,'source','file','small ghost',`data-id="${esc(id)}"`)).join('')}${a.node_ids.length?btn('Show in graph','angle-graph','graph','small',`data-id="${esc(a.id)}"`):''}</div>${Object.keys(a.scores).length?`<div class="mt12">${Object.entries(a.scores).map(([k,v])=>`<div class="details-line"><span>${esc(k.replaceAll('_',' '))}</span><span>${typeof v==='number'?Math.round(v*100)+'%':esc(v)}</span></div>`).join('')}<p class="tiny muted">Model estimates, not calibrated probabilities of truth.</p></div>`:''}</details></article>`).join('')}</div>${directionHTML()}</div>`;}
function outlineHTML(){const p=state.p;if(!p.outline.length)return empty('A shape before the sentences.','Select an angle first. The outline will connect each section or scene to its purpose and source material.','Develop outline','run-outline','list');const a=selectedAngle();return `<div class="toolbar"><div><h2 class="section-title">${esc(a?.title||'Working outline')}</h2><p class="section-desc">${p.outline.length} ${p.mode==='fiction'?'scenes':'sections'} · ${fmt(p.outline.reduce((n,s)=>n+s.target_words,0))} planned words</p></div>${btn('Add section','add-section','plus','small',busy()?'disabled':'')}</div><div class="outline-list">${p.outline.map((s,i)=>`<article class="outline-section" data-section="${esc(s.id)}"><div class="section-heading"><span class="outline-number">${String(i+1).padStart(2,'0')}</span><input aria-label="Section ${i+1} title" data-outline="title" data-id="${esc(s.id)}" value="${esc(s.title)}" ${busy()?'disabled':''}><div class="row">${ibtn('Move up','move-section','up',`data-id="${esc(s.id)}" data-offset="-1" ${i===0?'disabled':''}`)}${ibtn('Move down','move-section','down',`data-id="${esc(s.id)}" data-offset="1" ${i===p.outline.length-1?'disabled':''}`)}${ibtn('Remove section','remove-section','x',`data-id="${esc(s.id)}"`)}</div></div><div class="outline-fields"><div><label>What changes here?</label><textarea data-outline="purpose" data-id="${esc(s.id)}" rows="3" ${busy()?'disabled':''}>${esc(s.purpose)}</textarea></div><div class="beats"><label>Beats / key points · one per line</label><textarea data-outline="beats" data-id="${esc(s.id)}" rows="3" ${busy()?'disabled':''}>${esc(s.beats.join('\n'))}</textarea></div></div><div class="outline-foot"><div class="row wrap">${s.source_ids.map(id=>btn(id,'source','file','small ghost',`data-id="${esc(id)}"`)).join('')||'<span class="tiny muted">No source assigned</span>'}</div><label class="row tiny muted">Words <input class="words-input" type="number" min="50" max="5000" data-outline="target_words" data-id="${esc(s.id)}" value="${s.target_words}" ${busy()?'disabled':''}></label></div></article>`).join('')}</div><div class="row mt20 wrap">${btn('Write draft','run-draft','pen','primary',busy()?'disabled':'')}${btn('Regenerate outline','run-outline','refresh','ghost small',busy()?'disabled':'')}<span class="tiny muted">Sections are written sequentially, then reviewed as a whole.</span></div>`;}
function inlineMD(t){return esc(t).replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/\*([^*\n]+)\*/g,'<em>$1</em>').replace(/\[(S\d+)\]/g,'<button class="citation" data-action="source" data-id="$1">[$1]</button>');}
function markdown(text){return String(text||'').split(/\n\s*\n/).map(block=>{const lines=block.split('\n');if(/^#{1,3} /.test(lines[0])){const m=lines[0].match(/^(#{1,3}) (.*)$/);return `<h${m[1].length}>${inlineMD(m[2])}</h${m[1].length}>`+(lines.length>1?'<p>'+lines.slice(1).map(inlineMD).join('<br>')+'</p>':'');}if(/^\s*(\*\s*\*\s*\*|---)\s*$/.test(block))return '<hr>';if(lines.every(l=>/^[-*] /.test(l)))return '<ul>'+lines.map(l=>'<li>'+inlineMD(l.slice(2))+'</li>').join('')+'</ul>';if(lines.every(l=>/^\d+\. /.test(l)))return '<ol>'+lines.map(l=>'<li>'+inlineMD(l.replace(/^\d+\. /,''))+'</li>').join('')+'</ol>';if(/^> /.test(block))return '<blockquote>'+inlineMD(block.replace(/^> /gm,''))+'</blockquote>';return '<p>'+lines.map(inlineMD).join('<br>')+'</p>';}).join('');}
function writeHTML(){const p=state.p;return `<div class="writing-layout"><div class="panel"><div class="editor-toolbar"><div class="segmented" aria-label="Editor view">${['write','split','preview'].map(v=>`<button class="${state.view===v?'active':''}" data-action="editor-view" data-view="${v}">${v[0].toUpperCase()+v.slice(1)}</button>`).join('')}</div><div class="row">${ibtn('Version history','versions','clock')}${ibtn('Export draft','export','download')}</div></div><div class="editor-area ${state.view==='split'?'split':''}">${state.view!=='preview'?`<textarea class="manuscript" id="manuscript" aria-label="Manuscript editor" spellcheck="true" placeholder="Start writing here. Or develop your outline and let your model create the first draft." ${busy()?'readonly':''}>${esc(p.draft)}</textarea>`:''}${state.view!=='write'?`<article class="prose" id="draft-preview">${p.draft?markdown(p.draft):'<p class="muted">Your words, with room to breathe.</p>'}</article>`:''}</div><div class="editor-foot"><span id="word-count">${fmt(words(p.draft))} words · target ${fmt(p.brief.target_words)}</span><span><kbd class="keyboard">Ctrl S</kbd> save · Markdown supported</span></div></div><aside class="panel direction-panel"><div class="panel-header"><h2 class="section-title">Editorial desk</h2>${icon('pen')}</div><div class="panel-body"><div class="stack">${btn('Review the draft','run-review','check','primary',busy()||!p.draft?'disabled':'')}${btn('Revise with a direction','revise-dialog','pen','',busy()||!p.draft?'disabled':'')}${btn('Draft from outline','run-draft','spark','ghost small',busy()?'disabled':'')}</div>${reviewHTML()}<div class="evidence-card mt20"><span class="caps">Your own voice</span><p class="hint">Add a voice sample in Sources. It guides cadence and diction—not recycled sentences.</p>${btn('Edit creative brief','brief','settings','small ghost')}${p.mode==='fiction'?btn('Story ledger','story-ledger','book','small ghost'):''}</div><div class="mt20 tiny muted">${fmt(p.usage.calls)} provider calls · ${fmt(p.usage.input_tokens+p.usage.output_tokens)} tokens<br>${Number(p.usage.reported_cost||0)>0?'$'+Number(p.usage.reported_cost).toFixed(4)+' reported cost':'Cost unavailable for unpriced calls'}${p.usage.unpriced_calls?'<br>'+p.usage.unpriced_calls+' calls without provider-reported cost':''}</div></div></aside></div>`;}
function reviewHTML(){const r=state.p.review;if(!r?.summary)return '<div class="notice">The review checks argument and evidence in nonfiction; motivation, scene craft and canon in fiction. It is a second opinion—not a truth certificate.</div>';return `<div class="mt20"><span class="caps">Latest review</span><p class="small mt12">${esc(r.summary)}</p>${r.strengths.map(s=>`<p class="hint">✓ ${esc(s)}</p>`).join('')}${r.issues.map(i=>`<div class="review-issue"><span class="severity ${i.severity==='critical'?'critical':''}">${esc(i.severity||i.category||'Review')}</span><p>${esc(i.issue||i.description||i.problem||i.text||JSON.stringify(i))}</p>${i.quote||i.excerpt?`<blockquote>${esc(i.quote||i.excerpt)}</blockquote>`:''}${i.fix||i.suggestion?`<p>${esc(i.fix||i.suggestion)}</p>`:''}</div>`).join('')}${r.citation_audit?.sampled_claims?.length?`<details class="mt20"><summary class="small">Source-support check · ${r.citation_audit.sampled_claims.length} claims</summary>${r.citation_audit.sampled_claims.map(c=>`<div class="review-issue"><span class="severity">${esc(c.editor_judgment)}</span><p>${esc(c.claim)}</p>${c.quotes.map(q=>`<blockquote>${esc(q.quote)}</blockquote><button class="text-link" data-action="source" data-id="${esc(q.source_id)}">${esc(q.source_id)} · ${q.exact_match?'exact match':'not matched'}</button>`).join('')}</div>`).join('')}<p class="hint">Sampled claims only. A matching quote does not prove entailment.</p></details>`:''}<div class="notice">${esc(r.verdict||'Review available. Make the final editorial judgment yourself.')}<br>Reviews apply to the draft at the time they were run. Re-run after edits.</div></div>`;}
let graphView={x:0,y:0,k:1};
function drawGraph(){
 const svg=$('#graph-svg');if(!svg||!state.p)return;const g=state.p.graph;const search=state.search.toLowerCase();
 const focus=new Set(state.path);if(state.node){focus.add(state.node);g.edges.forEach(e=>{if(e.source===state.node)focus.add(e.target);if(e.target===state.node)focus.add(e.source);});}
 const degree={};g.edges.forEach(e=>{degree[e.source]=(degree[e.source]||0)+1;degree[e.target]=(degree[e.target]||0)+1;});
 let nodes=g.nodes.slice().sort((a,b)=>((focus.has(b.id)?10000:0)+(search&&b.label.toLowerCase().includes(search)?10000:0)+(degree[b.id]||0))-((focus.has(a.id)?10000:0)+(search&&a.label.toLowerCase().includes(search)?10000:0)+(degree[a.id]||0))).slice(0,180);
 const ids=new Set(nodes.map(n=>n.id)),edges=g.edges.filter(e=>ids.has(e.source)&&ids.has(e.target));
 if($('#graph-visibility'))$('#graph-visibility').textContent=g.nodes.length>180?` · showing ${nodes.length} most connected / matching nodes`:'';
 if(!Object.keys(state.layout).length){
  const positions={};nodes.forEach((n,i)=>{const angle=i*2.39996;const r=50+Math.sqrt(i/Math.max(nodes.length,1))*210;positions[n.id]={x:450+Math.cos(angle)*r*1.4,y:294+Math.sin(angle)*r};});
  for(let step=0;step<190;step++){
   const forces={};nodes.forEach(n=>forces[n.id]={x:(450-positions[n.id].x)*.018,y:(290-positions[n.id].y)*.018});
   for(let i=0;i<nodes.length;i++)for(let j=i+1;j<nodes.length;j++){const a=positions[nodes[i].id],b=positions[nodes[j].id];let dx=a.x-b.x,dy=a.y-b.y,d2=Math.max(150,dx*dx+dy*dy),f=11000/(d2*Math.sqrt(d2));forces[nodes[i].id].x+=dx*f;forces[nodes[i].id].y+=dy*f;forces[nodes[j].id].x-=dx*f;forces[nodes[j].id].y-=dy*f;}
   edges.forEach(e=>{const a=positions[e.source],b=positions[e.target],dx=b.x-a.x,dy=b.y-a.y,d=Math.hypot(dx,dy)||1,f=(d-145)*.055;forces[e.source].x+=dx/d*f;forces[e.source].y+=dy/d*f;forces[e.target].x-=dx/d*f;forces[e.target].y-=dy/d*f;});
   nodes.forEach(n=>{positions[n.id].x=Math.max(95,Math.min(805,positions[n.id].x+Math.max(-8,Math.min(8,forces[n.id].x))));positions[n.id].y=Math.max(90,Math.min(490,positions[n.id].y+Math.max(-8,Math.min(8,forces[n.id].y))));});
  }
  if(nodes.length>2){const xs=nodes.map(n=>positions[n.id].x),ys=nodes.map(n=>positions[n.id].y),minX=Math.min(...xs),minY=Math.min(...ys),dx=Math.max(1,Math.max(...xs)-minX),dy=Math.max(1,Math.max(...ys)-minY);nodes.forEach(n=>{positions[n.id].x=110+(positions[n.id].x-minX)/dx*680;positions[n.id].y=112+(positions[n.id].y-minY)/dy*352;});}
  for(let iteration=0;iteration<65;iteration++)for(let i=0;i<nodes.length;i++)for(let j=i+1;j<nodes.length;j++){const a=positions[nodes[i].id],b=positions[nodes[j].id],dx=a.x-b.x,dy=a.y-b.y,ox=(Math.min(30,nodes[i].label.length)+Math.min(30,nodes[j].label.length))*3+14-Math.abs(dx),oy=43-Math.abs(dy);if(ox>0&&oy>0){if(ox<oy*1.8){const d=Math.sign(dx)||1;a.x+=d*ox*.25;b.x-=d*ox*.25;}else{const d=Math.sign(dy)||1;a.y+=d*oy*.25;b.y-=d*oy*.25;}a.x=Math.max(100,Math.min(800,a.x));b.x=Math.max(100,Math.min(800,b.x));a.y=Math.max(100,Math.min(485,a.y));b.y=Math.max(100,Math.min(485,b.y));}}
  state.layout=positions;graphView={x:0,y:0,k:1};
 }
 nodes.forEach((n,i)=>{state.layout[n.id]||={x:120+(i%8)*90,y:110+Math.floor(i/8)*60};});
 const color=n=>['claim','character','person'].includes(n.kind)?'var(--blue)':['tension','conflict','event','risk','question'].includes(n.kind)?'var(--gold)':['canon','rule'].includes(n.kind)?'var(--purple)':'var(--accent)';
 svg.innerHTML=`<defs><marker id="arrowhead" viewBox="0 0 8 8" refX="18" refY="4" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M0 0 8 4 0 8" fill="var(--muted)"/></marker></defs><g id="graph-world" transform="translate(${graphView.x} ${graphView.y}) scale(${graphView.k})">${edges.map(e=>{const a=state.layout[e.source],b=state.layout[e.target];const hi=state.path.length?state.path.includes(e.source)&&state.path.includes(e.target):state.node&&(e.source===state.node||e.target===state.node);return `<g><line x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}" class="graph-edge ${['inferred','proposed','imported'].includes(e.status)?'inferred':''} ${hi?'highlight':focus.size?'dim':''}" marker-end="url(#arrowhead)"/><line x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}" stroke="transparent" stroke-width="13" data-edge="${esc(e.id)}" style="cursor:pointer"><title>${esc(e.relation)} · ${esc(e.status)}</title></line>${hi?`<text x="${(a.x+b.x)/2}" y="${(a.y+b.y)/2-5}" fill="var(--muted)" font-size="9" text-anchor="middle" style="paint-order:stroke;stroke:var(--panel);stroke-width:3px">${esc(e.relation.replaceAll('_',' '))}</text>`:''}</g>`;}).join('')}${nodes.map(n=>{const p=state.layout[n.id],r=8+Math.min(degree[n.id]||0,8)*.9,dim=(focus.size&&!focus.has(n.id))||(search&&!n.label.toLowerCase().includes(search));return `<g transform="translate(${p.x} ${p.y})" class="graph-node ${state.node===n.id?'active':''} ${dim?'dim':''}" data-node="${esc(n.id)}" role="button" tabindex="0" aria-label="${esc(n.label)}"><circle class="outer" r="${r+8}" fill="${color(n)}" opacity=".09"/><circle r="${r}" fill="${color(n)}" opacity=".93" stroke="var(--panel)" stroke-width="2"/>${state.p.brief.pinned_nodes.includes(n.id)?`<circle r="${r+5}" fill="none" stroke="${color(n)}" stroke-dasharray="2 3"/>`:''}<text y="${r+22}" text-anchor="middle" ${nodes.length>55&&!focus.has(n.id)&&!(search&&n.label.toLowerCase().includes(search))?'display="none"':''}>${esc(n.label.length>30?n.label.slice(0,28)+'…':n.label)}</text><title>${esc(n.description||n.label)}</title></g>`;}).join('')}</g>`;
 let drag=null,moved=false;
 const point=ev=>{const p=svg.createSVGPoint();p.x=ev.clientX;p.y=ev.clientY;return p.matrixTransform(svg.getScreenCTM().inverse());};
 svg.onpointerdown=ev=>{const p=point(ev),n=ev.target.closest('[data-node]'),ed=ev.target.closest('[data-edge]');if(ed)return;drag={id:n?.dataset.node,p,start:{...graphView}};moved=false;svg.setPointerCapture(ev.pointerId);};
 svg.onpointermove=ev=>{if(!drag)return;const p=point(ev);if(Math.hypot(p.x-drag.p.x,p.y-drag.p.y)>4)moved=true;if(!moved)return;if(drag.id){state.layout[drag.id]={x:(p.x-graphView.x)/graphView.k,y:(p.y-graphView.y)/graphView.k};const el=$(`[data-node="${CSS.escape(drag.id)}"]`,svg);el?.setAttribute('transform',`translate(${state.layout[drag.id].x} ${state.layout[drag.id].y})`);}else{graphView.x=drag.start.x+p.x-drag.p.x;graphView.y=drag.start.y+p.y-drag.p.y;$('#graph-world').setAttribute('transform',`translate(${graphView.x} ${graphView.y}) scale(${graphView.k})`);}};
 svg.onpointerup=()=>{if(!drag)return;const id=drag.id;drag=null;if(moved){drawGraph();return;}if(id)selectNode(id);};
 svg.onwheel=ev=>{ev.preventDefault();const p=point(ev),k=Math.max(.3,Math.min(3.5,graphView.k*(ev.deltaY<0?1.12:.89)));graphView.x=p.x-(p.x-graphView.x)*k/graphView.k;graphView.y=p.y-(p.y-graphView.y)*k/graphView.k;graphView.k=k;$('#graph-world').setAttribute('transform',`translate(${graphView.x} ${graphView.y}) scale(${k})`);};
 svg.onclick=ev=>{const e=ev.target.closest('[data-edge]');if(e){state.edge=e.dataset.edge;state.node=null;refreshDirection();}};
 svg.onkeydown=ev=>{const n=ev.target.closest('[data-node]');if(n&&['Enter',' '].includes(ev.key)){ev.preventDefault();selectNode(n.dataset.node);}};
}
function selectNode(id){state.node=id;state.edge=null;state.path=[];drawGraph();refreshDirection();}
function refreshDirection(){const e=$('.direction-panel');if(e)e.outerHTML=directionHTML();}
function paintJob(){const slot=$('#job-slot');if(!slot)return;const j=state.job;if(!j){slot.innerHTML='';return;}const msg=j.messages?.at(-1);slot.innerHTML=`<div class="job-bar"><div class="row">${busy()?'<span class="loader"></span>':icon(j.state==='completed'?'check':'alert')}<div class="spacer"><div class="job-message">${esc(typeof msg==='string'?msg:msg?.text||j.action+' · '+j.state)}</div><div class="job-usage">${esc(j.state)} · ${fmt(j.usage?.calls)} calls · ${fmt((j.usage?.input_tokens||0)+(j.usage?.output_tokens||0))} tokens ${j.usage?.reported_cost?'· $'+Number(j.usage.reported_cost).toFixed(4)+' reported':''}${j.error?' · '+esc(j.error):''}</div></div>${busy()?btn('Cancel','cancel-job','stop','small ghost'):ibtn('Dismiss job result','dismiss-job','x')}</div><div class="progress"><i style="width:${Math.max(0,Math.min(100,Number(j.progress)||0))}%"></i></div></div>`;}
async function startJob(action,instruction=''){if(!editable())return;await flush();if(!state.settings.allow_cloud&&!['localhost','127.0.0.1','[::1]'].includes(new URL(state.settings.base_url).hostname)){toast('Connect your model and allow sending selected material before running AI actions.');showSettings();return;}if(!state.settings.model&&state.settings.provider!=='codex'){toast('Choose a writing model in Connections first.');showSettings();return;}state.job=await api('/projects/'+state.p.id+'/jobs',{action,instruction});render();poll();}
function poll(){clearTimeout(pollTimer);if(!state.job)return;const jid=state.job.id,pid=state.p.id;pollTimer=setTimeout(async()=>{try{const j=await api('/jobs/'+jid);if(state.job?.id!==jid||state.p?.id!==pid)return;state.job=j;paintJob();if(['queued','running'].includes(j.state)){poll();return;}const p=await api('/projects/'+state.p.id);state.p=p;syncSummary();if(j.state==='completed'){state.tab={graph:'graph',angles:'angles',outline:'outline',draft:'write',review:'write',revise:'write',humanize:'write',deslop:'write',both:'write',voice:'sources'}[j.action]||state.tab;state.layout={};toast('Finished. Your project is saved locally.');}else toast(j.error||'Job stopped. Saved versions are still available.',j.state==='failed');render();}catch(e){toast(e.message,true);poll();}},1000);}
function newDialog(mode='nonfiction'){showModal('Begin a new project','You can change the direction as the work develops.',`<div class="form-grid"><div class="form-full"><label for="project-title">Project title</label><input id="project-title" placeholder="A working title is enough" maxlength="200"></div><div><label for="project-mode">Writing mode</label><select id="project-mode"><option value="nonfiction" ${mode==='nonfiction'?'selected':''}>Nonfiction — evidence & argument</option><option value="fiction" ${mode==='fiction'?'selected':''}>Fiction — characters & consequences</option></select></div><div><label for="project-words">Target length</label><input id="project-words" type="number" value="1800" min="200" max="20000"></div><div class="form-full"><label for="project-premise">What is on your mind?</label><textarea id="project-premise" rows="4" placeholder="A question, a premise, an argument you want to explore…"></textarea></div></div>`,btn('Create project','create-project','arrow','primary'));}
function rolesHTML(value){return ['evidence','canon','inspiration','voice'].map(v=>`<option value="${v}" ${v===value?'selected':''}>${v[0].toUpperCase()+v.slice(1)}</option>`).join('');}
function pasteDialog(){showModal('Bring a source into the studio','Keep the original text. The graph will link its claims back to these passages.',`<div class="form-grid"><div><label>Source title</label><input id="source-title" placeholder="Article, notes or chapter title"></div><div><label>Use as</label><select id="source-role">${rolesHTML(state.p.mode==='fiction'?'canon':'evidence')}</select></div><div class="form-full"><label>Source text</label><textarea class="long-text" id="source-body" placeholder="Paste the full text…"></textarea></div><div><label>Original URL (optional)</label><input id="source-url" type="url"></div><div><label>Author (optional)</label><input id="source-author"></div></div>`,btn('Add source','add-text','plus','primary'),true);}
function urlDialog(){showModal('Import from the web','Fetches a public page once. No account, cookies or paywall bypass.',`<label>Article URL</label><input id="url-input" type="url" placeholder="https://…" style="width:100%"><label class="mt12">Use as</label><select id="source-role">${rolesHTML('evidence')}</select><div class="notice">Some sites block automated access. Paste the article or upload a document instead when that happens. This action contacts the website, but does not send its content to an AI model.</div>`,btn('Import article','add-url','download','primary'));}
function sourceDialog(id,ev){const s=state.p.sources.find(s=>s.id===id);if(!s){toast('Source not found in this project.',true);return;}let text=esc(s.text);if(ev?.verified&&ev.start>=0)text=esc(s.text.slice(0,ev.start))+'<mark id="source-highlight">'+esc(s.text.slice(ev.start,ev.end))+'</mark>'+esc(s.text.slice(ev.end));showModal(s.title,`${s.id} · ${fmt(words(s.text))} words · ${s.kind}`,`<div class="row wrap"><span class="chip">${esc(s.role)}</span><span class="tiny muted">${esc(s.author)} ${esc(s.published)}</span></div>${s.url?`<p class="tiny muted mt12" style="overflow-wrap:anywhere">${esc(s.url)}</p>`:''}<div class="source-text">${text}</div>${s.warnings.map(w=>`<div class="notice">${esc(w)}</div>`).join('')}<div class="row mt20"><label for="change-role">Use as</label><select id="change-role" data-id="${esc(id)}">${rolesHTML(s.role)}</select></div>`,btn('Save role','save-source-role','check','primary'),true);setTimeout(()=>$('#source-highlight')?.scrollIntoView({block:'center'}),40);}
function briefDialog(){const b=state.p.brief,f=state.p.mode==='fiction';const field=(id,label,value,type='input')=>`<div class="${type==='textarea'?'form-full':''}"><label for="b-${id}">${esc(label)}</label>${type==='textarea'?`<textarea id="b-${id}" rows="3">${esc(value)}</textarea>`:`<input id="b-${id}" value="${esc(value)}">`}</div>`;showModal('The creative brief','Your intention is a first-class input—not an afterthought.',`<div class="form-grid">${field('audience','Audience',b.audience)}${field('format','Format',b.format)}${field('direction','Central question / direction',b.direction,'textarea')}${field('voice','Voice & style',b.voice,'textarea')}${f?field('genre','Genre',b.genre)+field('pov','Point of view',b.pov)+field('tense','Tense',b.tense)+field('canon','Canon / non-negotiable world rules',b.canon,'textarea'):''}${field('avoid','Avoid',b.avoid,'textarea')}<div><label>Target words</label><input id="b-target_words" type="number" min="200" max="20000" value="${b.target_words}"></div><div><label>Exploration / evidence discipline</label><p class="hint">${b.originality}% exploration · ${b.rigor}% discipline<br>Adjust the sliders beside the graph.</p></div></div>`,btn('Save brief','save-brief','check','primary'),true);}
function angleDialog(id){const a=state.p.angles.find(a=>a.id===id)||{id:uid(),title:'',thesis:'',hook:'',why:'',counterargument:'',questions:[],motif:'author',node_ids:[],edge_ids:[],source_ids:[],scores:{},decision:'author',score_engine:'author',score:null};state.editingAngle=a;showModal(id?'Refine this angle':'Your angle, your judgment','Say what this piece should do. You do not have to accept a model’s recommendation.',`<div class="form-grid"><div class="form-full"><label>Title</label><input id="a-title" value="${esc(a.title)}"></div><div class="form-full"><label>Thesis / premise</label><textarea id="a-thesis" rows="4">${esc(a.thesis)}</textarea></div><div class="form-full"><label>Opening hook</label><textarea id="a-hook" rows="2">${esc(a.hook)}</textarea></div><div class="form-full"><label>Relevant challenge / central tension (optional)</label><textarea id="a-counter" rows="2">${esc(a.counterargument)}</textarea></div><div class="form-full"><label>Questions to resolve · one per line</label><textarea id="a-questions" rows="3">${esc(a.questions.join('\n'))}</textarea></div></div>`,btn('Save & select','save-angle','check','primary'),true);}
function settingsForm(){const s=state.settings;const opt=(v,label,current)=>`<option value="${v}" ${current===v?'selected':''}>${label}</option>`;const text=(id,label,val,attrs='')=>`<div><label for="s-${id}">${label}</label><input id="s-${id}" value="${esc(val)}" ${attrs}></div>`;return `<div class="form-grid"><div><label>Writing provider</label><select id="s-provider">${opt('openrouter','OpenRouter',s.provider)}${opt('openai-compatible','OpenAI-compatible / local',s.provider)}${opt('anthropic','Anthropic',s.provider)}</select></div>${text('base_url','API base URL',s.base_url)}${text('model','Writing model ID',s.model,'list="model-list" placeholder="Choose any model your provider supports"')}${text('editor_model','Editor model (blank = same)',s.editor_model,'list="model-list"')}${text('extraction_model','Extraction model (blank = same)',s.extraction_model,'list="model-list"')}<div><label>Model discovery</label>${btn('Load available models','load-models','refresh','small')}<datalist id="model-list"></datalist></div><div class="form-full"><label for="key-llm">Writing-provider key</label><input id="key-llm" type="password" autocomplete="new-password" placeholder="${s.keys?.llm?'Saved securely · leave blank to keep':'Paste key (not required for a keyless local server)'}"><span class="tiny muted">OpenRouter can also use the dedicated key below.</span></div><div><label>OpenRouter key (also used by JEV)</label><input id="key-openrouter" type="password" autocomplete="new-password" placeholder="${s.keys?.openrouter?'Saved securely · leave blank to keep':'Optional separate key'}"></div><div><label>TypeSafe key</label><input id="key-typesafe" type="password" autocomplete="new-password" placeholder="${s.keys?.typesafe?'Saved securely · leave blank to keep':'For direct JEV access'}"></div><div><label>JEV decision connection</label><select id="s-jev_provider">${opt('auto','Auto — OpenRouter, then TypeSafe',s.jev_provider)}${opt('openrouter','OpenRouter',s.jev_provider)}${opt('typesafe','Direct TypeSafe',s.jev_provider)}${opt('off','Off — structural exploration only',s.jev_provider)}</select></div>${text('jev_model','JEV model ID',s.jev_model)}<div class="form-full"><label class="checkbox-row"><input id="s-allow_cloud" type="checkbox" ${s.allow_cloud?'checked':''}><span><strong>Allow AI actions to send project material to my configured providers.</strong><br>Graph extraction, angle discovery, JEV decisions, drafting and review send the passages needed for that action. Never include confidential material without permission.</span></label><label class="checkbox-row"><input id="s-remember_keys" type="checkbox" ${s.remember_keys?'checked':''}><span>Remember keys using the operating system’s secure storage. Current storage: <strong>${esc(s.key_storage||'session only')}</strong>. No plaintext fallback.</span></label><label class="checkbox-row"><input id="s-refine" type="checkbox" ${s.refine?'checked':''}><span>After drafting, allow one bounded revision. Keep it only when the configured JEV check prefers it and citation checks pass; otherwise save it as a candidate version.</span></label></div></div><details class="mt20"><summary>Advanced limits & Graphify</summary><div class="form-grid mt20">${text('max_calls','Provider requests per job',s.max_calls,'type="number" min="5" max="500"')}${text('max_output_tokens','Maximum output tokens per call',s.max_output_tokens,'type="number" min="1000" max="64000"')}${text('context_chars','Context budget (characters, not tokens)',s.context_chars,'type="number" min="20000" max="1500000"')}${text('max_candidates','Graph candidates to judge',s.max_candidates,'type="number" min="6" max="80"')}<div><label>Graph engine</label><select id="s-graph_engine">${opt('native','Native evidence extraction',s.graph_engine)}${opt('graphify','Graphify (external process)',s.graph_engine)}</select></div>${text('graphify_executable','Custom Graphify executable (blank = bundled)',s.graphify_executable)}<div class="form-full notice">The Windows release includes Graphify. The external process uses the selected extraction model through GraphPaper, including Codex OAuth, and shares the job request budget. Leave the custom executable blank for the bundled runtime. Import graph.json remains a separate no-inference action.</div></div></details><div class="row mt12 wrap">${btn('Test writer','test-writer','check','small')}${btn('Test JEV','test-jev','check','small')}${btn('Clear saved keys','clear-keys','trash','small ghost')}<span class="tiny muted">Tests use a small provider request.</span></div><p class="tiny muted mt20" style="overflow-wrap:anywhere">Project storage: ${esc(s.data_directory)}</p>`;}
function showSettings(){showModal('Connections & settings','Bring your models. Keep your manuscripts local.',settingsForm(),btn('Save connections','save-settings','check','primary'),true);}
async function saveSettings(){const s={...state.settings};for(const k of ['provider','base_url','model','editor_model','extraction_model','jev_provider','jev_model','graph_engine','graphify_executable'])s[k]=$('#s-'+k).value.trim();for(const k of ['max_calls','max_output_tokens','context_chars','max_candidates'])s[k]=Number($('#s-'+k).value);for(const k of ['allow_cloud','remember_keys','refine'])s[k]=$('#s-'+k).checked;s.api_keys={};for(const k of ['llm','openrouter','typesafe'])s.api_keys[k]=$('#key-'+k).value||null;state.settings=await api('/settings',s,'PUT');$('#modal-status').textContent='Saved. Keys are not returned to the browser.';}
function chooseFile(accept,multiple,callback){const el=document.createElement('input');el.type='file';el.accept=accept;el.multiple=multiple;el.onchange=()=>callback([...el.files]).catch(e=>toast(e.message,true));el.click();}
async function uploadFiles(files){if(!editable())return;await flush();let successes=0;for(const file of files){try{if(file.size>20*1024*1024)throw new Error(file.name+' exceeds 20 MB.');const form=new FormData();form.append('file',file);form.append('role',state.p.mode==='fiction'?'canon':'evidence');state.p=await api('/projects/'+state.p.id+'/sources/file',form);successes++;}catch(e){toast(file.name+': '+e.message,true);}}syncSummary();render();if(successes)toast(`${successes} source${successes===1?'':'s'} added.`);}
function setupDrops(){const el=$('#dropzone');if(!el)return;el.ondragover=e=>{e.preventDefault();el.classList.add('drag');};el.ondragleave=()=>el.classList.remove('drag');el.ondrop=e=>{e.preventDefault();el.classList.remove('drag');uploadFiles([...e.dataTransfer.files]).catch(e=>toast(e.message,true));};el.onkeydown=e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();chooseFile('.pdf,.docx,.md,.txt,.html,.htm,.csv',true,uploadFiles);}};}
async function exportFile(kind){await flush();if(window.pywebview?.api?.save_export){const r=await window.pywebview.api.save_export(state.p.id,kind);if(r.error)throw new Error(r.error);if(r.saved)toast('Export saved.');return;}const res=await fetch(`/api/projects/${state.p.id}/export/${kind}`,{headers:{'X-GraphPaper':'1'},credentials:'same-origin'});if(!res.ok)throw new Error((await res.json()).detail||'Export failed.');const data=await res.blob(),url=URL.createObjectURL(data),a=document.createElement('a');a.href=url;a.download=res.headers.get('Content-Disposition')?.match(/filename="([^"]+)"/)?.[1]||'GraphPaper.'+kind;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function exportDialog(){showModal('Let the work leave the studio','Export a draft or keep a portable copy of the entire project.',`<div class="export-options">${[['docx','Word document','Editable manuscript with bibliography','file'],['md','Markdown','Plain text with source references','pen'],['html','Print-ready HTML','Open in your browser to print or save as PDF','eye'],['json','Project backup','Sources, graph, angles, outline and current draft','folder'],['graph','Knowledge graph','Graph JSON for external tools','graph']].map(([kind,title,desc,ic])=>`<button class="export-card" data-action="export-file" data-kind="${kind}">${icon(ic)}<strong>${title}</strong><small>${desc}</small></button>`).join('')}</div><div class="notice">Project backups contain your source texts and current draft, but never API keys. Historical draft versions stay in the local database; export an earlier version by restoring it first.</div>`);}
async function versionsDialog(){await flush();const rows=await api('/projects/'+state.p.id+'/revisions');state.versions=rows;showModal('Versions, not regrets','Generated checkpoints and earlier drafts are kept separately.',`${rows.length?rows.map(r=>`<div class="version-item"><div><strong class="small">${esc(r.label)}</strong><small>${esc(new Date(r.created).toLocaleString())} · ${fmt(words(r.draft))} words</small></div><div class="row">${btn('Read','read-version','eye','small ghost',`data-id="${esc(r.id)}"`)}${btn('Restore','restore-version','clock','small',`data-id="${esc(r.id)}"`)}</div></div>`).join(''):'<p class="muted">Versions appear once you edit or generate a draft.</p>'}`,'',true);}
async function handleAction(el){const a=el.dataset.action,p=state.p,id=el.dataset.id;
 if(a?.startsWith('run-'))return startJob(a.slice(4));
 switch(a){
 case 'close-modal':closeModal();break;
 case 'menu':$('.sidebar').classList.toggle('open');break;
 case 'home':await flush();state.p=null;render();break;
 case 'new':newDialog(el.dataset.mode||'nonfiction');break;
 case 'create-project':{const title=$('#project-title').value.trim()||'Untitled project',mode=$('#project-mode').value,w=Number($('#project-words').value),direction=$('#project-premise').value;if(w<200||w>20000)throw new Error('Choose 200–20,000 target words.');let n=await api('/projects',{title,mode});n=await api('/projects/'+n.id,{version:n.version,brief:{...n.brief,target_words:w,direction}},'PATCH');closeModal();await setProject(n,'sources');break;}
 case 'demo':{const n=await api('/demo',{mode:el.dataset.mode||'nonfiction'});await setProject(n,'graph');break;}
 case 'open-project':await openProject(id);break;
 case 'tab':await flush();state.tab=el.dataset.tab;render();break;
 case 'theme':state.settings.theme=state.settings.theme==='light'?'dark':'light';state.settings=await api('/settings',state.settings,'PUT');document.documentElement.dataset.theme=state.settings.theme;break;
 case 'settings':await flush();showSettings();break;
 case 'save-settings':await saveSettings();closeModal();render();toast('Connections saved.');break;
 case 'load-models':await saveSettings();$('#modal-status').textContent='Loading model IDs…';{const out=await api('/models');const list=Array.isArray(out)?out:out.models||[];$('#model-list').innerHTML=list.map(m=>`<option value="${esc(typeof m==='string'?m:m.id)}"></option>`).join('');$('#modal-status').textContent=`${list.length} models loaded. Type in a model field to choose.`;}break;
 case 'test-writer':case 'test-jev':await saveSettings();$('#modal-status').textContent='Testing…';{const r=await api('/test-connection',{kind:a==='test-jev'?'jev':'writer'});$('#modal-status').textContent=r.message;}break;
 case 'clear-keys':{state.settings=await api('/settings',{...state.settings,api_keys:{llm:'',openrouter:'',typesafe:''}},'PUT');showSettings();toast('Saved keys cleared for this session and secure store.');break;}
 case 'brief':if(editable())briefDialog();break;
 case 'save-brief':{const b={...p.brief};for(const k of ['audience','format','direction','voice','genre','pov','tense','canon','avoid'])if($('#b-'+k))b[k]=$('#b-'+k).value;b.target_words=Number($('#b-target_words').value);if(b.target_words<200||b.target_words>20000)throw new Error('Choose 200–20,000 words.');p.brief=b;queueSave({brief:b});await flush();closeModal();render();break;}
 case 'upload':chooseFile('.pdf,.docx,.md,.txt,.html,.htm,.csv',true,uploadFiles);break;
 case 'paste':if(editable())pasteDialog();break;
 case 'url':if(editable())urlDialog();break;
 case 'add-text':await flush();{const r=await api('/projects/'+p.id+'/sources/text',{title:$('#source-title').value||'Pasted source',text:$('#source-body').value,role:$('#source-role').value,url:$('#source-url').value,author:$('#source-author').value});state.p=r;syncSummary();closeModal();render();toast('Source added.');}break;
 case 'add-url':{await flush();$('#modal-status').textContent='Fetching article…';el.disabled=true;try{state.p=await api('/projects/'+p.id+'/sources/url',{url:$('#url-input').value,role:$('#source-role').value});syncSummary();closeModal();render();toast('Article imported.');}finally{el.disabled=false;}break;}
 case 'source':sourceDialog(id);break;
 case 'source-toggle':if(editable()){await flush();const s=p.sources.find(s=>s.id===id);state.p=await api('/projects/'+p.id+'/sources/'+id,{enabled:!s.enabled},'PATCH');render();}break;
 case 'save-source-role':if(editable()){await flush();const s=$('#change-role');state.p=await api('/projects/'+p.id+'/sources/'+s.dataset.id,{role:s.value},'PATCH');closeModal();render();}break;
 case 'evidence':{const item=p.graph.nodes.find(n=>n.id===state.node)||p.graph.edges.find(e=>e.id===state.edge);const ev=item?.evidence[Number(el.dataset.index)];if(ev)sourceDialog(ev.source_id,ev);break;}
 case 'pin':case 'unpin':case 'exclude':case 'clear-exclusions':if(editable()){const b={...p.brief};if(a==='pin')b.pinned_nodes=[...new Set([...b.pinned_nodes,id])];if(a==='unpin')b.pinned_nodes=b.pinned_nodes.filter(x=>x!==id);if(a==='exclude'){b.excluded_nodes=b.excluded_nodes.includes(id)?b.excluded_nodes.filter(x=>x!==id):[...b.excluded_nodes,id];b.pinned_nodes=b.pinned_nodes.filter(x=>x!==id);}if(a==='clear-exclusions')b.excluded_nodes=[];p.brief=b;queueSave({brief:b});refreshDirection();if(state.tab==='graph')drawGraph();}break;
 case 'zoom-in':case 'zoom-out':{const k=Math.min(3.5,Math.max(.3,graphView.k*(a==='zoom-in'?1.2:.8)));graphView.x=450-(450-graphView.x)*k/graphView.k;graphView.y=295-(295-graphView.y)*k/graphView.k;graphView.k=k;drawGraph();break;}
 case 'fit-graph':graphView={x:0,y:0,k:1};drawGraph();break;
 case 'find-path':{const options=p.graph.nodes.map(n=>`<option value="${esc(n.id)}">${esc(n.label)}</option>`).join('');showModal('Follow a connection','Find a conceptual path. A path is not a proof.',`<div class="form-grid"><div><label>From</label><select id="path-a">${options}</select></div><div><label>To</label><select id="path-b">${options}</select></div></div>`,btn('Find path','get-path','branch','primary'));if(p.graph.nodes.length>1)$('#path-b').selectedIndex=1;break;}
 case 'get-path':{const a=$('#path-a').value,b=$('#path-b').value,r=await api('/projects/'+p.id+'/graph/path?a='+encodeURIComponent(a)+'&b='+encodeURIComponent(b));state.path=r.path;state.node=null;closeModal();if(!r.path.length)toast('No connection was found.');render();break;}
 case 'import-graph':if(editable())chooseFile('.json',false,async files=>{await flush();const f=files[0];if(f.size>20e6)throw new Error('Graph file exceeds 20 MB.');state.p=await api('/projects/'+p.id+'/graph/import',JSON.parse(await f.text()));state.layout={};state.tab='graph';render();toast('Graph imported. Its relationships are unverified until anchored to sources.');});break;
 case 'select-angle':if(editable()){p.selected_angle=id;p.feedback.push({angle_id:id,decision:'selected',at:new Date().toISOString()});queueSave({selected_angle:id,feedback:p.feedback});await flush();render();}break;
 case 'edit-angle':if(editable())angleDialog(id);break;
 case 'custom-angle':if(editable())angleDialog();break;
 case 'save-angle':{const a={...state.editingAngle,title:$('#a-title').value,thesis:$('#a-thesis').value,hook:$('#a-hook').value,counterargument:$('#a-counter').value,questions:$('#a-questions').value.split('\n').filter(Boolean),score:null,score_engine:'author edited',scores:{},decision:'author'};if(!a.title.trim()||!a.thesis.trim())throw new Error('Give the angle a title and a thesis or premise.');const n=p.angles.findIndex(x=>x.id===a.id);if(n>=0)p.angles[n]=a;else p.angles.push(a);p.selected_angle=a.id;queueSave({angles:p.angles,selected_angle:a.id});await flush();closeModal();render();break;}
 case 'angle-graph':{const a=p.angles.find(x=>x.id===id);state.path=a.node_ids;state.node=null;state.tab='graph';render();break;}
 case 'add-section':if(editable()){p.outline.push({id:uid(),title:p.mode==='fiction'?'New scene':'New section',purpose:'',beats:[],source_ids:[],target_words:300});queueSave({outline:p.outline});render();}break;
 case 'move-section':if(editable()){const i=p.outline.findIndex(s=>s.id===id),j=i+Number(el.dataset.offset);if(j>=0&&j<p.outline.length){[p.outline[i],p.outline[j]]=[p.outline[j],p.outline[i]];queueSave({outline:p.outline});render();}}break;
 case 'remove-section':if(editable()){p.outline=p.outline.filter(s=>s.id!==id);queueSave({outline:p.outline});render();}break;
 case 'editor-view':await flush();state.view=el.dataset.view;render();break;
 case 'revise-dialog':showModal('What should change?','The current draft is saved before revision.',`<label>Editorial direction</label><textarea id="revision-instruction" rows="6" placeholder="Sharpen the central argument; preserve my voice. Or: make the character’s choice harder without changing the ending."></textarea>`,btn('Revise draft','do-revise','pen','primary'));break;
 case 'do-revise':{const text=$('#revision-instruction').value;closeModal();await startJob('revise',text);break;}
 case 'cancel-job':await api('/jobs/'+state.job.id+'/cancel',{});toast('Cancellation requested. The current provider request may still complete.');break;
 case 'dismiss-job':state.job=null;paintJob();break;
 case 'story-ledger':showModal('Continuity ledger','A generated record of what has happened—not new author-approved canon.',`<div class="source-text">${esc(JSON.stringify(p.story_state,null,2))}</div><div class="notice">Check this against the draft and your canon. It helps later scenes remember earlier developments, but remains an AI summary.</div>`,'',true);break;
 case 'versions':await versionsDialog();break;
 case 'read-version':{const r=state.versions.find(x=>x.id===id);showModal(r.label,'A saved version. Reading it does not change your manuscript.',`<article class="prose">${markdown(r.draft)}</article>`,btn('Restore this version','restore-version','clock','primary',`data-id="${esc(id)}"`),true);break;}
 case 'restore-version':if(editable()){await flush();state.p=await api('/projects/'+p.id+'/revisions/'+id+'/restore',{});closeModal();state.tab='write';render();toast('Version restored; the previous draft is preserved.');}break;
 case 'export':exportDialog();break;
 case 'export-file':await exportFile(el.dataset.kind);break;
 case 'import-project':chooseFile('.json',false,async files=>{if(files[0].size>25e6)throw new Error('Project backup exceeds 25 MB.');const p=await api('/import',JSON.parse(await files[0].text()));await setProject(p);toast('Project imported as a separate copy.');});break;
 case 'project-options':showModal('Project settings','Rename or remove this workspace.',`<label>Title</label><input id="rename-title" value="${esc(p.title)}" style="width:100%"><div class="notice">Deleting a project also removes its local draft history. Export a backup first.</div>`,btn('Delete project','delete-project','trash','ghost danger')+btn('Save title','rename-project','check','primary'));break;
 case 'rename-project':if(editable()){queueSave({title:$('#rename-title').value.slice(0,200)||'Untitled project'});await flush();closeModal();render();}break;
 case 'delete-project':if(editable()){showModal('Delete this project?','This removes the local sources, graph, draft and saved versions.',`<p>${esc(p.title)}</p><p class="hint">This cannot be undone. Export a backup first.</p>`,btn('Keep project','close-modal','','ghost')+btn('Delete permanently','confirm-delete','trash','danger'));}break;
 case 'confirm-delete':await api('/projects/'+p.id,undefined,'DELETE');state.projects=state.projects.filter(x=>x.id!==p.id);state.p=null;pending={};closeModal();render();break;
 case 'help':showModal('A studio, not an autopilot','The author keeps the decisions that matter.',`<div class="stack"><h3>1. Bring the material</h3><p class="small muted">Evidence is citable material. Canon is established fictional truth. Inspiration suggests possibilities; voice samples guide style. Keep these roles distinct.</p><h3>2. Explore before committing</h3><p class="small muted">The graph exposes claims and relationships. Exact source matches verify where a quote came from—not whether the claim is true. Imported or inferred relationships remain visibly distinct.</p><h3>3. Choose a direction</h3><p class="small muted">JEV evaluates graph opportunities, angle fit, evidence gaps and revision decisions. Its estimates are judgments, not guaranteed accuracy. You can edit or replace every angle.</p><h3>4. Shape, write, review</h3><p class="small muted">Edit the outline, generate section by section, inspect the full-draft review and revise. Fiction checks motivation and canon; nonfiction checks argument and evidence. Source references are clickable.</p><h3>5. Keep what is yours</h3><p class="small muted">Projects live locally. Model requests happen only after consent. Export Word, Markdown, print-ready HTML, graph JSON or a project backup. Settings and API keys never appear in backups.</p></div><div class="notice">GraphPaper does not automatically fact-check the web or prove that a source supports a conclusion. Read the linked passages. There is no promise that adding a graph will outperform a strong direct-writing prompt on every task.</div>`,'',true);break;
 }
}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;e.preventDefault();handleAction(el).catch(err=>{if($('.modal'))modalError(err.message);else toast(err.message,true);});});
document.addEventListener('input',e=>{const el=e.target;if(el.id==='graph-search'){state.search=el.value;drawGraph();return;}if(el.id==='manuscript'){if(busy())return;state.p.draft=el.value;queueSave({draft:el.value});if($('#draft-preview'))$('#draft-preview').innerHTML=markdown(el.value);$('#word-count').textContent=fmt(words(el.value))+' words · target '+fmt(state.p.brief.target_words);return;}if(el.dataset.brief){if(busy())return;const key=el.dataset.brief;state.p.brief[key]=['originality','rigor','rhetorical_force'].includes(key)?Number(el.value):el.value;if($('#'+key+'-value'))$('#'+key+'-value').textContent=el.value+'%';queueSave({brief:{...state.p.brief}});return;}if(el.dataset.outline){if(busy())return;const s=state.p.outline.find(s=>s.id===el.dataset.id),k=el.dataset.outline;if(k==='target_words'){const n=Number(el.value);if(n<50||n>5000)return;s[k]=n;}else s[k]=k==='beats'?el.value.split('\n').filter(Boolean):el.value;queueSave({outline:state.p.outline});}});
document.addEventListener('change',e=>{if(e.target.id==='s-provider'){const b=$('#s-base_url');b.value={openrouter:'https://openrouter.ai/api/v1','openai-compatible':'https://api.openai.com/v1',anthropic:'https://api.anthropic.com/v1'}[e.target.value];}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();flush().then(()=>toast('Saved locally.')).catch(x=>toast(x.message,true));}if(e.key==='Escape'&&$('.modal'))closeModal();if(e.key==='Tab'&&$('.modal')){const focus=$$('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),[tabindex="0"]',$('.modal')).filter(x=>x.offsetParent!==null),first=focus[0],last=focus.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
window.addEventListener('beforeunload',e=>{if(Object.keys(pending).length||state.save==='Saving…'){e.preventDefault();e.returnValue='';}});
async function boot(){try{const b=await api('/bootstrap');state.settings=b.settings;state.projects=b.projects;const id=storage.getItem('graphpaper.last');if(id&&b.projects.some(p=>p.id===id)){state.p=await api('/projects/'+id);state.tab=state.p.graph.nodes.length?'graph':'sources';state.job=b.jobs.find(j=>j.project_id===id)||null;if(state.job)poll();}render();}catch(e){$('#app').innerHTML=`<div class="empty"><h2>The studio couldn’t open.</h2><p>${esc(e.message)}</p><p>Close and reopen GraphPaper to establish a fresh local session.</p></div>`;}}
boot();

// Native close uses a save handshake, not eval (our CSP deliberately forbids it).
window.graphpaperRequestClose=async()=>{
 try{await flush();if(window.pywebview?.api?.request_close)await window.pywebview.api.request_close();}
 catch(e){await window.pywebview?.api?.cancel_close?.().catch(()=>{});toast('Not closed: '+e.message,true);}
};
function notifyDesktopReady(){window.pywebview?.api?.notify_ready?.().catch(()=>{});}
window.addEventListener('pywebviewready',notifyDesktopReady);
notifyDesktopReady();
